<?php /** @var array $defs @var array $counts @var array $maturity @var int $mYear */ require __DIR__ . '/_fmt.php'; ?>
<div class="page-head"><div><h1><?= icon('layers') ?> <?= e(t('reg.title')) ?></h1><p class="sub"><?= e(t('reg.subtitle')) ?></p></div></div>
<div class="kpis"><?php foreach ($defs as $k => $d): $c = $counts[$k]; ?><a class="kpi<?= $c['overdue'] ? ' alert' : '' ?>" href="<?= e(url('registers') . '?r=' . $k) ?>"><div class="v"><?= (int)$c['total'] ?></div>
<div class="l"><?= icon($d['icon']) ?> <strong><?= e(t(sprintf('reg.%s', $k))) ?></strong><br><?= e(t(sprintf('reg.%s_desc', $k))) ?><?php if ($d['open']): ?><br><?= e(t('reg.open_n', ['n' => $c['open']])) ?><?= $c['overdue'] ? ' · <span class="badge danger">' . e(t('reg.overdue_n', ['n' => $c['overdue']])) . '</span>' : '' ?><?php endif; ?></div></a><?php endforeach; ?></div>
<?php if ($maturity): ?><section class="card"><h2><?= e(t('reg.maturity_profile', ['y' => $mYear])) ?></h2><div class="table-wrap"><table class="data"><thead><tr><th><?= e(t('reg.f_axis')) ?></th><th><?= e(t('reg.f_level')) ?></th><th><?= e(t('reg.f_target')) ?></th><th><?= e(t('reg.gap')) ?></th></tr></thead><tbody>
<?php foreach ($maturity as $axis => [$lv, $tg]): ?><tr><td><?= e($opt('axis', $axis)) ?></td><td><?= $lv === null ? '—' : str_repeat('●', $lv) . str_repeat('○', 5 - $lv) ?></td><td><?= $tg === null ? '—' : (int)$tg ?></td><td><?= $lv !== null && $tg !== null && $tg > $lv ? '<span class="badge warn">' . ($tg - $lv) . '</span>' : '—' ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
